={{ JSON.stringify((() => {
  const S = $('Settings').first().json;
  const st = $('Start from daily scan').first().json;
  const r = $json;
  const t = (v) => String(v ?? '').trim();
  const rowCount = $('Fetch invoice now').all().filter((i) => t(i.json.invoice_no) !== '').length;
  const found = rowCount === 1 && t(r.invoice_no) !== '' && t(r.invoice_no) === t(st.invoice_no);
  const dueOk = /^\d{4}-\d{2}-\d{2}$/.test(t(r.due_date)) && DateTime.fromISO(t(r.due_date), { zone: 'utc' }).isValid;
  const balOk = /^-?\d+(\.\d{1,2})?$/.test(t(r.balance));
  const bal = balOk ? Math.round(Number(t(r.balance)) * 100) : 0;
  const days = dueOk ? Math.round(DateTime.fromISO($now.toFormat('yyyy-LL-dd'), { zone: 'utc' }).diff(DateTime.fromISO(t(r.due_date), { zone: 'utc' }), 'days').days) : null;
  const tier = days === null ? 'none' : (days < 1 ? 'not_overdue' : (days <= Number(S.t1_max) ? 't1' : (days <= Number(S.t2_max) ? 't2' : 't3')));
  const status = t(r.status).toLowerCase();
  const collectable = found && dueOk && balOk && t(r.doc_type).toLowerCase() === 'invoice' && status === 'open' && bal > 0;
  return {
    found: found, row_count: rowCount, collectable: collectable, current_tier: tier, balance_minor: bal, days_past_due: days,
    stop_status: (found && (status === 'paid' || (balOk && bal <= 0))) ? 'stopped_paid' : 'stopped_changed',
    invoice_no: t(r.invoice_no), customer_name: t(r.customer_name).replace(/\s+/g, ' '), currency: t(r.currency).toUpperCase(), due_date: t(r.due_date)
  };
})()) }}

